import {courtPositions} from './config.js';
export function normalizeRoster(roster){return roster.map((p,i)=>({...p,role:p.role|| (i<9?'court':'bench'),courtPosition:p.role==='bench'?null:p.courtPosition||(i<9?courtPositions[i]:null)})).sort((a,b)=>{if(a.role!==b.role)return a.role==='court'?-1:1;if(a.recordOrder!==undefined||b.recordOrder!==undefined)return (a.recordOrder??a.order??0)-(b.recordOrder??b.order??0);if(a.role==='court')return courtPositions.indexOf(a.courtPosition)-courtPositions.indexOf(b.courtPosition);return (a.order||0)-(b.order||0)});}
export function createLineup(){let selected=[],slots=Array(9).fill(null);return {select(id,checked){if(checked&&!selected.includes(id)){selected.push(id);const empty=slots.indexOf(null);if(empty>=0)slots[empty]=id;}if(!checked){selected=selected.filter(x=>x!==id);slots=slots.map(x=>x===id?null:x);}},place(id,index){if(!selected.includes(id)||!Number.isInteger(index)||index<0||index>=9)throw Error('배치할 선수와 위치를 확인하세요.');const old=slots.indexOf(id),other=slots[index];slots[index]=id;if(old>=0)slots[old]=other;},toBench(id){if(!selected.includes(id))throw Error('선수를 선택하세요.');slots=slots.map(x=>x===id?null:x);},read(){return {selected:[...selected],slots:[...slots],bench:selected.filter(id=>!slots.includes(id))};},entries(){return [...slots.flatMap((id,i)=>id?[{playerId:id,role:'court',courtPosition:courtPositions[i]}]:[]),...selected.filter(id=>!slots.includes(id)).map(id=>({playerId:id,role:'bench',courtPosition:null}))].map((p,order)=>({...p,order}));}};}
